static const size_t EMOJI_TABLE_SIZE = sizeof(EMOJI_TABLE) / sizeof(EMOJI_TABLE[0]);

const char* find_emoji(std::string_view name) {
    auto it = std::lower_bound(
        EMOJI_TABLE, EMOJI_TABLE + EMOJI_TABLE_SIZE, name,
        [](const EmojiEntry& entry, std::string_view val) {
            return std::string_view(entry.name) < val;
        }
    );
    if (it != EMOJI_TABLE + EMOJI_TABLE_SIZE && std::string_view(it->name) == name) {
        return it->utf8;
    }
    return nullptr;
}

